// 关卡 02 · 参数是一段 JSON 字符串
//
// tool_calls[].function.arguments 是一个 string,里面装的还是 JSON。
// 这一关只做两件事:把它拆开,以及决定拆不开的时候怎么办。
package main

import (
	"encoding/json"
	"fmt"
)

// handle 处理一次工具调用,返回的字符串就是要回给模型的那条 tool 结果。
func handle(call toolCall) string {
	if call.Name != "bash" {
		// 模型要了一个不存在的工具,而它仍然在等一条结果。
		[[1]]
	}

	var args struct {
		Command string `json:"command"`
	}

	// 从 call.Arguments 里取出 command
	if err := [[2]]; err != nil {
		[[3]]
	}

	return fakeBash(args.Command)
}

func main() {
	for _, call := range transcript {
		fmt.Printf("%s %s(%s)\n", call.ID, call.Name, call.Arguments)
		fmt.Printf("  -> %s\n\n", handle(call))
	}
}

package main

import (
	"fmt"
	"strings"
)

type toolCall struct {
	ID   string
	Name string

	// 注意类型。这是一个 string,不是一个对象 —— 接口就是这么送的,
	// 里面那层 JSON 有它自己的一套转义。
	Arguments string
}

// 四次调用。后两次是真实模型每天都会送来的东西。
var transcript = []toolCall{
	{ID: "call_1", Name: "bash", Arguments: `{"command":"ls"}`},
	{ID: "call_2", Name: "bash", Arguments: `{"command":"grep -n \"tool_call_id\" main.go"}`},
	{ID: "call_3", Name: "bash", Arguments: `{"command":`},
	{ID: "call_4", Name: "read_file", Arguments: `{"path":"main.go"}`},
}

func fakeBash(command string) string {
	switch command {
	case "ls":
		return "main.go  transcript.go"
	case `grep -n "tool_call_id" main.go`:
		return "main.go:16:\tToolCallID string"
	}
	return "bash: 不认识这条命令: " + command
}

// matchCommand 用字符串匹配去取 command 的值,不解 JSON。
// 它在 call_1 上是对的。放它进来就是为了让你看见它在 call_2 上会怎么样。
func matchCommand(raw string, out *string) error {
	const key = `"command":"`
	i := strings.Index(raw, key)
	if i < 0 {
		return fmt.Errorf("找不到 command: %s", raw)
	}
	rest := raw[i+len(key):]
	j := strings.Index(rest, `"`)
	if j < 0 {
		return fmt.Errorf("command 没有收尾: %s", raw)
	}
	*out = rest[:j]
	return nil
}
